(()=>{const root=document.querySelector('#products'),track=root?.querySelector('.category-track');if(!track)return;const slides=[...track.children],tabs=[...root.querySelectorAll('[data-family]')];let active=0;function select(i){active=(i+slides.length)%slides.length;slides.forEach((s,j)=>{s.inert=j!==active});track.style.transform=`translateX(-${active*100}%)`;tabs.forEach((t,j)=>t.setAttribute('aria-pressed',String(j===active)));root.querySelector('.category-count').textContent=`0${active+1} / 02`;}tabs.forEach(t=>t.addEventListener('click',()=>select(+t.dataset.family)));root.querySelectorAll('[data-direction]').forEach(b=>b.addEventListener('click',()=>select(active+ +b.dataset.direction)));root.addEventListener('keydown',e=>{if(e.target.closest('.category-toolbar')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();select(active+(e.key==='ArrowRight'?1:-1));tabs[active].focus()}});let start;root.querySelector('.category-viewport').addEventListener('touchstart',e=>{start={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});root.querySelector('.category-viewport').addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)select(active+(dx<0?1:-1));start=null},{passive:true});function hash(){if(location.hash==='#smart-home'){select(1);root.scrollIntoView({block:'start'})}else if(['#products','#smart-lighting'].includes(location.hash))select(0)}document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.getAttribute('href')==='/#smart-home'&&location.hash==='#smart-home'){select(1);root.scrollIntoView({block:'start'})}});window.addEventListener('hashchange',hash);hash()})();
